#!/usr/bin/env python3
"""Rebuild clean chat transcripts from Codex rollout JSONL files."""

from __future__ import annotations

import json
import re
import sys
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from pathlib import Path

CST = timezone(timedelta(hours=8))

SKIP_PREFIXES = (
    "<environment_context>",
    "<app-context>",
    "<collaboration_mode>",
    "<skills_instructions>",
    "<permissions instructions>",
    "<multi_agent_mode>",
    "<in-app-browser-context",
)


def is_system_noise(text: str) -> bool:
    t = text.strip()
    if not t:
        return True
    for p in SKIP_PREFIXES:
        if t.startswith(p):
            return True
    # pure wrapper blocks such as "<turn_aborted>...</turn_aborted>"
    if re.fullmatch(r"<[a-z_-]+>.*</[a-z_-]+>", t, flags=re.S) and len(t) < 400:
        return True
    return False


@dataclass
class Turn:
    role: str
    phase: str
    text: str
    ts: str


@dataclass
class Session:
    sid: str
    path: Path
    started: str = ""
    ended: str = ""
    cwd: str = ""
    turns: list[Turn] = field(default_factory=list)


def local(ts: str) -> str:
    if not ts:
        return ""
    try:
        dt = datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(CST)
    except ValueError:
        return ts
    return dt.strftime("%Y-%m-%d %H:%M:%S")


def parse(path: Path) -> Session:
    s = Session(sid=path.stem.split("-")[-1], path=path)
    with path.open(encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                continue
            ts = obj.get("timestamp", "")
            if not s.started:
                s.started = ts
